interface CleanupResource {
    name: string;
    disposed: boolean;
    dispose(): void;
}

function makeResource(name: string): CleanupResource {
    return { name, disposed: false, dispose() { this.disposed = true; } };
}

type AuditEntry = { action: string; resource: string };

async function managedOp(
    names: string[],
    failSet: Set<string>,
    audit: AuditEntry[]
): Promise<{ results: string[]; resources: CleanupResource[] }> {
    const results: string[] = [];
    const resources: CleanupResource[] = [];

    for (const name of names) {
        const outer = makeResource(name);
        resources.push(outer);
        audit.push({ action: 'acquire', resource: name });
        try {
            if (failSet.has(name)) {
                throw new Error(`${name}_failed`);
            }
            const inner = makeResource(`${name}_inner`);
            resources.push(inner);
            try {
                await new Promise(r => setTimeout(r, 1));
                results.push(`${name}:ok`);

golden_completion:
    } finally {
        inner.dispose();
        audit.push({ action: 'release', resource: inner.name });
    }
} catch (err: unknown) {
    const msg = err instanceof Error ? err.message : String(err);
    results.push(`${name}:error:${msg}`);
} finally {
